def can_detect_all_viruses(G, N, M, mutation_table, antibodies):
    def bfs(start_gene):
        from collections import deque

        queue = deque([start_gene])
        visited = set()
        visited.add(start_gene)

        while queue:
            current = queue.popleft()
            if current in mutation_table:
                for replacement in mutation_table[current]:
                    if replacement not in visited:
                        visited.add(replacement)
                        queue.append(replacement)

        return visited

    def is_detectable(virus, antibodies):
        for antibody in antibodies:
            if antibody in virus:
                return True
        return False

    def find_shortest_undetectable(virus, antibodies):
        from itertools import product

        for length in range(1, 100):  # Arbitrary large number to ensure we find the shortest
            for combination in product([0, 1], repeat=length):
                if combination not in antibodies and combination not in virus:
                    return length
        return -1  # Should not reach here due to problem constraints

    results = []

    for gene in range(2, G):
        reachable_genes = bfs(gene)
        virus = set()

        for g in reachable_genes:
            if g < 2:
                virus.add(tuple([g]))
            else:
                virus.update(mutation_table.get(g, []))

        if not virus:
            results.append("YES")
        else:
            virus = {tuple(v) for v in virus}
            antibodies = {tuple(a) for a in antibodies}

            if all(is_detectable(v, antibodies) for v in virus):
                results.append("YES")
            else:
                shortest_undetectable = min(find_shortest_undetectable(v, antibodies) for v in virus)
                results.append(f"NO {shortest_undetectable}")

    return results

